.ProseMirror { position: relative; }.ProseMirror { overflow-wrap: break-word; white-space: break-spaces; font-variant-ligatures: none; font-feature-settings: "liga" 0; }.ProseMirror [contenteditable="false"] { white-space: normal; }.ProseMirror [contenteditable="false"] [contenteditable="true"] { white-space: pre-wrap; }.ProseMirror pre { white-space: pre-wrap; }img.ProseMirror-separator { display: inline !important; border-width: medium !important; border-style: none !important; border-color: currentcolor !important; border-image: none !important; margin: 0px !important; width: 0px !important; height: 0px !important; }.ProseMirror-gapcursor { display: none; pointer-events: none; position: absolute; margin: 0px; }.ProseMirror-gapcursor::after { content: ""; display: block; position: absolute; top: -2px; width: 20px; border-top: 1px solid black; animation: 1.1s steps(2, start) 0s infinite normal none running ProseMirror-cursor-blink; }@keyframes ProseMirror-cursor-blink { 
  100% { visibility: hidden; }
}.ProseMirror-hideselection ::selection { background: transparent; }.ProseMirror-hideselection * { caret-color: transparent; }.ProseMirror-focused .ProseMirror-gapcursor { display: block; }.tippy-box[data-animation="fade"][data-state="hidden"] { opacity: 0; }
